return ['domain'=>'zinn-backups','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'so_SO','project-id-version'=>'zinn-backups','pot-creation-date'=>'2026-10-08T09:17:23+00:00','po-revision-date'=>'2026-10-08T09:17:23+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Backups'=>'Zinn® Backups','https://zinndigital.com/wordpress-plugins/zinn-backups'=>'https://zinndigital.com/wordpress-plugins/zinn-backups','Backs up your WordPress files and database to your own storage — Dropbox, Google Drive, Cloudflare R2, Amazon S3 or any S3-compatible bucket — restores them in one go, and imports backups made by other backup and migration plugins.'=>'Wuxuu faylashada iyo xog-ururintaada WordPress dib ugu kaydiyaa kaydkaaga gaarka ah — Dropbox, Google Drive, Cloudflare R2, Amazon S3 ama baaldi kasta oo ku habboon S3 — wuxuuna ku soo celiyaa hal mar, isagoo soo dhoofinaya kaydyo ay sameeyeen furmooyin kale oo kaydinta iyo wareejinta ah.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Backups'=>'Kaydinta xogta','Get Pro: schedules, several storages, encryption'=>'Hel Pro: jadwalada, dhowr kayd, siraynta','Working…'=>'Shaqaynaya…','Finished'=>'Dhammaystiran','Failed'=>'Wuu fashilmay','Cancelled'=>'La baajiyay','Cancel'=>'Kansal garee','Restore'=>'Soo celi','Delete'=>'Tir','Delete this backup from your storage? This cannot be undone.'=>'Ma ka tirtirtaa kaydintan kaydsigaaga? Tan dib looma celin karo.','No backups yet. Press “Back up now” to make the first one.'=>'Weli ma jiraan wax keyd ah. Riix "Keydi hadda" si aad u sameyso midka koowaad.','Reading your storage…'=>'Akhrinta keydkaaga…','a complete backup, as opposed to an incremental oneFull backup'=>'Kayd buuxa','a backup holding only what changed since an earlier oneIncremental backup'=>'Soo celin kordhaysa','Encrypted'=>'La qariyey','From another site'=>'Laga keenay goob kale','Database'=>'Xog-ururin','Files'=>'Faylasha','Uploading %1$s: %2$s%%'=>'Soo gelinta %1$s: %2$s%%','Sign in to Dropbox in the window that opened, then paste the code Dropbox shows you:'=>'Gal Dropbox daaqadda furantay, ka dibna dheji koodhka Dropbox ku tusayo:','Saved.'=>'Waa la keydiyay.','Remove this destination from the plugin? The backups stored in it are not deleted.'=>'Meeshan lagu kaydiyo ma laga saaraa furaha? Nuqullada kaydka ah ee ku dhex jira lama tirtirayo.','Reload the page to see the restored site.'=>'Dib u soo rari bogga si aad u aragto goobta dib loo soo celiyay.','Storage'=>'Kaydinta','Import & migrate'=>'Soo daji & guuri','Settings'=>'Hagaajinta','Sections'=>'Qaybaha','Google Drive is connected.'=>'Google Drive waa ku xidhan yahay.','Google Drive could not be connected.'=>'Google Drive lama xiriirin karin.','Details'=>'Faahfaahinta','Back up now'=>'Hadda kaydi','Backups go to your own storage, not this server. <a href="%s">Connect your storage</a> first.'=>'Kaydintu waxay aadaysaa kaydkaaga gaarka ah, ma aha adeegahan. Marka hore <a href="%s">ku xidh kaydkaaga</a>.','What to back up'=>'Waxa la kaydinayo','Files and database'=>'Faylasha iyo xog-ururinta','Database only'=>'Kaliya xog-ururin','Files only'=>'Faylasha kaliya','Note (optional)'=>'Xusuusin (ikhtiyaari)','Each part is uploaded to your storage and removed from this server before the next one is made, so the backup never takes up room on your hosting.'=>'Qayb kasta waxaa lagu shubaa kaydkaaga waxaana laga saaraa seerfarkan ka hor inta aan la samayn qaybta xigta, markaa koobiga kaydku marnaba meel kama qaato martigelintaada.','Your backups'=>'Koobiyadaada kaydka ah','Refresh'=>'Dib u cusboonaysii','Restore this backup'=>'Soo celi kaydkan','Passphrase'=>'Weerada sirta ah','I understand this replaces this site’s files and database with the backup’s. Files that are not in the backup are kept.'=>'Waan fahamsanahay in tani ay ku beddelayso faylashan iyo kaydka xogta goobtan kuwa ku jira kaydka koobiyeynta. Faylasha aan ku jirin kaydka koobiyeynta waa la xafidayaa.','Recent activity'=>'Dhaqdhaqaaqii ugu dambeeyay','Backup'=>'Kaydinta xogta','Restore / import'=>'Soo celi / soo dhoofso','Running'=>'Shaqeynaya','Your storage'=>'Kaydintaada' . "\0" . 'Goobahaaga kaydinta','No storage yet. Choose where your backups go below.'=>'Weli ma jirto kayd. Hoos ka dooro meesha ay ku soconayaan kaydintaadu.','Ready'=>'Diyaar','Not connected'=>'Kuma xirna','Connect'=>'Ku xir','Test'=>'Tijaabi','Edit'=>'Wax ka beddel','Remove'=>'Ka saar','Add storage'=>'Ku dar kaydinta','Backups go to one storage destination. To use a different one, edit or remove the one above.'=>'Kaydintu waxay aadaan hal meel oo kaydin ah. Si aad mid kale u isticmaasho, wax ka beddel ama ka saar kan sare.','Kind of storage'=>'Nooca kaydinta','Name (for you)'=>'Magaca (adiga kuu gaar ah)','Provider'=>'Bixiye','Cloudflare account id'=>'Aqoonsiga koontada Cloudflare','Endpoint address'=>'Cinwaanka barta dhamaadka','Region'=>'Gobol','Bucket'=>'Baaldiga','Access key id'=>'Aqoonsiga furaha gelitaanka','Secret access key'=>'Furaha gelitaanka qarsoodiga ah','Leave empty to keep the saved key'=>'Faaruq uga tag si aad u hayso furaha la kaydiyay','For Cloudflare R2: in the Cloudflare dashboard open R2, create a bucket, then “Manage R2 API tokens” → create a token with Object Read & Write for that bucket, and copy the access key id and secret here.'=>'Wixii ku saabsan Cloudflare R2: gudaha dashboard-ka Cloudflare ka fur R2, samee baaldi (bucket), kaddibna “Manage R2 API tokens” → u samee token leh Object Read & Write baaldigaas, oo halkan ku koobiyeey aqoonsiga furaha gelitaanka (access key id) iyo sirta.','Dropbox app key'=>'Furaha abka Dropbox','Create an app at dropbox.com/developers/apps (Scoped access, App folder) with the files.content.read, files.content.write and files.metadata.read permissions, and copy its App key here. Save, then press Connect.'=>'Ka samee barnaamij dropbox.com/developers/apps (Scoped access, App folder) adigoo siinaya rukhsadaha files.content.read, files.content.write iyo files.metadata.read, ka dibna halkaan ku soo koobi App key-giisa. Keydi, ka dibna riix Connect.','OAuth client id'=>'Aqoonsiga macmiilka OAuth','OAuth client secret'=>'Sirta macmiilka OAuth','Leave empty to keep the saved secret'=>'Faaruq uga tag si aad u hayso sirta la keydiyay','In Google Cloud Console, enable the Google Drive API, then create an OAuth client of type “Web application” with this address as an authorised redirect URI:'=>'Gudaha Google Cloud Console, ka shaqaysii Google Drive API, ka dibna samee macmiilka OAuth ee nooca "Web application" oo ciwaankani yahay URI dib-u-hagaajin oo la oggol yahay:','Save, then press Connect. The plugin only sees the files it creates.'=>'Keydi, ka dibna riix Xiriiri. Furaha wuxuu arkaa oo keliya faylasha uu isagu abuuro.','Folder inside the storage (optional)'=>'Galka ku dhex jira keydka (ikhtiyaari)','Save storage'=>'Kaydso meel kaydinta','Import a backup from another plugin or host'=>'Kaga soo dhoobso kayd firiiric (backup) plugin kale ama meel kale','Bring a site in from a backup made by UpdraftPlus, All-in-One WP Migration (.wpress), Duplicator (zip), BackWPup, WPvivid, Jetpack VaultPress Backup, BlogVault, Zinn® Migrate, or any zip/tar archive of a WordPress site with its .sql dump. The content goes into wp-content and the database replaces this site’s; addresses are changed to this site’s automatically.'=>'Ka keen goob kayd ay samaysay UpdraftPlus, All-in-One WP Migration (.wpress), Duplicator (zip), BackWPup, WPvivid, Jetpack VaultPress Backup, BlogVault, Zinn® Migrate, ama fayl kasta oo zip/tar ah oo ah goobta WordPress oo ay ku jirto daadinteeda .sql. Waxyaabaha ku jira waxay galaan wp-content xog-ururintuna waxay beddelaysaa tan goobtan; ciwaannada waxaa si toos ah loogu beddelaa kuwa goobtan.','Upload from your computer'=>'Ka soo geli kombiyuutarkaaga','Choose every file of the backup at once (UpdraftPlus makes several). Large files are sent in small pieces, so your host’s upload limit does not apply.'=>'Dooro fayl kasta oo kaydka ah hal mar (UpdraftPlus wuxuu sameeyaa dhowr). Faylasha waaweyn waxaa loo diraa qaybo yaryar, markaa xadka gelinta martigeliyahaagu ma khuseeyo.','Or from links (Google Drive, Dropbox or any download address)'=>'Ama xiriirinta (Google Drive, Dropbox ama cinwaan kasta oo lagu soo dejiyo)','One link per line. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link; turn sharing off again afterwards.'=>'Halkii xariiqba hal xiriiriye. Google Drive iyo Dropbox, la wadaag faylka "qof kasta oo haysta xiriiriyaha" oo dheji xiriiriyahaas; ka dibna mar kale dami wadaagidda.','Or a file already on this server'=>'Ama fayl horey ugu jiray adeegahan','Upload archives by FTP or your host’s file manager into %s and reload this page.'=>'Ku soo dheji kaydadka FTP ama maareeyaha faylka ee martigeliyahaaga %s oo dib u cusbooneysii boggan.','Or a deploy code from another site'=>'Ama koodhka daabacaadda ee goob kale','If another site gave you a Zinn® Backups deploy code, paste it here to copy that backup onto this site without sharing its storage keys. A code works for a few hours; treat it like a password.'=>'Haddii degel kale uu ku siiyay koodhka geynta ee Zinn® Backups, halkan ku dheji si aad koobigaas ugu soo guuriso degelkan adigoon la wadaagin furayaasha kaydinta. Koodhku waxa uu shaqaynayaa dhawr saacadood oo keliya; ula dhaqan sida erayga sirta ah.','Passphrase (only if that backup is encrypted)'=>'Weeraha sirta ah (haddii keliya koobigaas la xafiday)','Import'=>'Soo dhoofso','I understand the import replaces this site’s content and database. After it, sign in with an account from the imported site.'=>'Waan fahamsanahay in soo dejintu ay beddelayso nuxurka iyo xog-ururinta goobtan. Ka dib, ku gal akoon ka socda goobta la soo dejiyay.','Moving to Zinn® hosting?'=>'Ma u wareegaysaa martigelinta Zinn®?','Zinn Digital® can move your site for you from your old host. If your old host gives you no FTP, SSH or control-panel access, install Zinn® Migrate on the old site; it makes one archive you can import here or hand to Zinn®.'=>'Zinn Digital® waxay kaaga soo rari kartaa boggaaga meeshii hore ee lagu martigelin jiray. Haddii aysan meeshaadii hore ku siinaynin gelitaanka FTP, SSH ama control-panel, ku rakib Zinn® Migrate boggaagii hore; waxay samaynaysaa hal kayd oo aad halkan ku soo dejisan karto ama u dhiibi karto Zinn®.','What goes into a backup'=>'Maxaa ku jira kaydka','Include WordPress’s own files (wp-admin, wp-includes). Usually not needed: WordPress can always be reinstalled.'=>'Ku dar faylasha WordPress u gaarka ah (wp-admin, wp-includes). Badanaa looma baahna: WordPress mar kasta dib ayaa loo rakibi karaa.','Also leave out these folders or files (one per line, relative to the WordPress folder)'=>'Sidoo kale ka tag galka ama faylashan (midkiiba sadar, marka loo eego galka WordPress)','Always left out: caches, update scratch space, and other backup plugins’ own archive folders:'=>'Had iyo jeer laga tagay: kaydadka xusuusta (caches), goobta ku meel gaarka ah ee cusboonaysiinta, iyo galalka kaydka ee furayaasha kale ee kaydinta:','Size of each part (MB)'=>'Cabirka qayb kasta (MB)','Save settings'=>'Kaydi habaynta','A backup part could not be opened for writing. Check that wp-content has free space.'=>'Qayb ka mid ah kaydka dib-u-soo-celinta lama furi karin si wax loogu qoro. Hubi in wp-content ay leedahay meel bannaan.','A backup part could not be written. Check that wp-content has free space.'=>'Qayb ka mid ah kaydinta lama qori karin. Hubi in wp-content uu leeyahay meel bannaan.','Connect a storage destination on the Storage tab first: backups are kept in your own storage, not on this server.'=>'Marka hore ku xidh meel kaydin ah tab-ka Storage: koobiyada kaydka ah waxa lagu hayaa kaydkaaga gaarka ah, ee laguma hayo seerfarkan.','Multisite networks are not supported yet.'=>'Shabakadaha goobaha badan (multisite) weli lama taageero.','This server’s PHP has no ZipArchive extension. Ask your host to enable it.'=>'PHP-ga server-kani ma laha kordhinta ZipArchive. Waydiiso martigeliyahaaga inuu awood siiyo.','Starting'=>'Bilaabaya','Listing files'=>'Liis gareynta faylasha','Backing up the database'=>'Kaydinta xog-ururinta','Packing files'=>'Xiridda faylasha','Uploading to your storage'=>'Waxaa loo rarayaa keydkaaga','Finishing'=>'Dhameystiraya','The backup reached an unknown stage.'=>'Kaydintu waxay gaadhay marxalad aan la garanayn.','Backup %s started.'=>'Kaydinta %s waa la bilaabay.','Found %1$s files (%2$s).'=>'Waxaa la helay %1$s fayl (%2$s).','Database: %1$d tables, %2$s rows, %3$s compressed.'=>'Xog-ururin: %1$d miisas, %2$s safaf, %3$s la cufay.','Backup complete: %1$s stored in %2$d destination.'=>'Kaydintu way dhammaatay: %1$s waxa lagu kaydiyay %2$d meel.' . "\0" . 'Kaydintii waa dhammaatay: %1$s waxaa lagu keydiyay %2$d goobood.','Some parts already uploaded could not be removed from your storage; they are in an incomplete backup folder and are never offered for restore.'=>'Qaybo ka mid ah oo horay loo soo geliyay lagama saari karo kaydintaada; waxay ku jiraan faylka kaydinta aan dhamaystirnayn weligoodna looma soo bandhigo soo celinta.','A storage destination was removed while the backup was running.'=>'Goob kaydin ayaa la saaray intii uu socday kaydinta nuqulka.','That is not a backup folder.'=>'Taasi ma aha gal kayd ah.','That storage destination is no longer saved on this site.'=>'Goobtaas wax lagu kaydiyo dib dambe looguma kaydinayo goobtan.','Later incremental backups are built on this one. Delete those first.'=>'Koobiyada dambe ee kordhinta ah waxay ku dhisan yihiin kan. Marka hore tirtir kuwaas.','This file is not an encrypted Zinn® Backups file.'=>'Faylkan ma aha fayl Zinn® Backups ah oo la siray.','The backup could not be decrypted: the passphrase is wrong or the file is damaged.'=>'Koobka kaydka ah lama furfuri karin: weedha sirta ah ayaa khaldan ama faylka ayaa waxyeeloobay.','The encrypted backup file is incomplete.'=>'Faylka kaydka ee sirta ah ma dhammaystirna.','The database file could not be written. Check that wp-content has free space.'=>'Faylka keydka xogta lama qori karin. Hubi in wp-content uu leeyahay meel bannaan.','That is not a deploy code. A deploy code starts with zbdeploy1.'=>'Taasi ma aha koodhka daadgureynta. Koodhka daadgureynta wuxuu ka bilaabmaa zbdeploy1.','That deploy code is damaged. Copy it again from the other site.'=>'Koodhkaas geynta wuu waxyeeloobay. Mar kale kaga soo koobi saytka kale.','The deploy code has expired or its backup was deleted. Make a new code on the other site.'=>'Xeerka geynta wuu dhacay ama kaydkiisii waa la tirtiray. Ka samee koodh cusub goobta kale.','That deploy code does not point at a Zinn® Backups backup.'=>'Koodkaas hawlgelinta ma tilmaamayo kaydka Zinn® Backups.','The deploy code has expired. Make a new code on the other site.'=>'Xeerka hawlgelinta wuu dhacay. Ka samee koodh cusub goobta kale.','The server stopped honouring partial downloads. Start the import again.'=>'Server-ku wuxuu joojiyay aqbalida soo dejinta qayb ahaan ah. Dib u billow soo dejinta xogta.','The link opened a web page instead of a file. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link.'=>'Xiriirintu waxay furtay bog internet ah halkii ay ka furi lahayd fayl. Google Drive iyo Dropbox, la wadaag faylka "qof kasta oo haysta xiriirinta" oo dheji xiriirintaas.','The link answered with HTTP %d.'=>'Xiriirintu waxay kaga jawaabtay HTTP %d.','The file list could not be written.'=>'Lama qori karin liiska faylka.','The storage service could not be reached: %s'=>'Adeegga kaydinta lama gaari karin: %s','%1$s answered with HTTP %2$d: %3$s'=>'%1$s wuxuu kaga jawaabay HTTP %2$d: %3$s','no details given'=>'Faahfaahin lama bixin','You are not allowed to manage backups.'=>'Laguma oggola inaad maamusho koobiyada kaydka ah.','Tick the box to confirm that the restore replaces this site’s files and database.'=>'Calaamadee sanduuqa si aad u xaqiijiso in dib-u-soo-celintu ay beddelayso faylasha iyo xog-ururinta boggan.','Save the destination first.'=>'Marka hore kaydi halka loo socdo.','Connected: a test file was written and removed.'=>'Waa ku xidhan yahay: fayl tijaabo ah ayaa la qoray oo meesha laga saaray.','Enter the app key of your Dropbox app first (see the steps beside the form).'=>'Marka hore geli furaha app-ka ee Dropbox-kaaga (eeg tillaabooyinka ku xiga foomka).','This kind of storage does not sign in.'=>'Kaydkan noocan ah ma galo.','The sign-in expired. Press Connect again.'=>'Galitaanku wuu dhacay. Mar kale riix Ku xidh.','Dropbox is connected.'=>'Dropbox waa ku xiran yahay.','Settings saved.'=>'Habsocodka waa la keydiyay.','Another backup, restore or import is running. Wait for it to finish, or cancel it.'=>'Kayd kale, soo celin ama soo dejin ayaa socota. Sug inta ay ka dhammaanayso, ama jooji.','The upload was not started properly. Start again.'=>'Soo-gelintu si sax ah uma bilaaban. Dib u bilow.','The chunk did not arrive. Your server may limit upload sizes; try again.'=>'Qaybtu ma soo gaarin. Seerfarkaagu waxa laga yaabaa inuu xaddido cabbirka soo gelinta; mar kale isku day.','Tick the box to confirm that the import replaces this site’s content and database.'=>'Calaamadee sanduuqa si aad u xaqiijiso in soo dejintu beddelayso nuxurka iyo xog-ururinta boggan.','Choose an archive to import: upload it, paste a link, or pick one from the import folder.'=>'Dooro kayd aad soo dejiso: soo geli, dheji xiriiriye, ama mid ka dooro galka soo dejinta.','Hosting customer? Get %1$d%% off %2$s'=>'Macaamiil hosting ah? Ka hel %1$d%% dhimis %2$s','As a Zinn Digital® hosting customer you get a personal code for %d%% off your first payment. Renewals are at the normal price.'=>'Adigoo ah macaamiil martigelinta Zinn Digital® waxaad helaysaa koodh shakhsi ah oo loogu talagalay %d%% dhimis ah lacag-bixintaada ugu horreysa. Cusboonaysiinta waxay ku socotaa qiimaha caadiga ah.','Get my %d%% code and go to checkout'=>'Hel koodkayga %d%% oo u gudub bixinta','Sorry, you are not allowed to do that.'=>'Waan ka xunnahay, laguma oggola inaad taas samayso.','This discount is for customers with a paid hosting plan in good standing. Free trials do not qualify.'=>'Qiimo dhimistan waxaa loogu talagalay macaamiisha leh qorshe martigelineed oo lacag ah oo xaaladdiisu wanaagsan tahay. Tijaabooyinka bilaashka ah ma u qalmaan.','You have already used your hosting-customer discount for this plugin.'=>'Hore ayaad u isticmaashay qiimo dhimista macaamiisha martigelinta ee qalabkan.','We could not get your code just now. Please try again in a few minutes.'=>'Hadda ma aannu heli karin koodhkaaga. Fadlan isku day mar kale dhowr daqiiqo ka dib.','Reading the backup'=>'Akhrinta kaydka','Downloading the archive'=>'Soo dejinta kaydka','Recognising the archive'=>'Aqoonsashada kaydka','Restoring files'=>'Soo celinta faylasha','Downloading the database'=>'Soo dejinta xog-ururinta','Restoring the database'=>'Dib u soo celinta kaydka xogta','Updating the site address'=>'Cusboonaysiinta ciwaanka bogga','Switching to the restored database'=>'U beddelashada xog-ururinta dib loo soo celiyay','The restore reached an unknown stage.'=>'Soo celintu waxay gaadhay heer aan la garanayn.','This folder has no complete Zinn® Backups backup in it (the manifest is missing).'=>'Galalkan kuma jiraan koobiyayn buuxda oo Zinn® Backups ah (manifest-kii waa maqan yahay).','This backup is encrypted. Enter its passphrase to restore it.'=>'Kaydkan dib-u-soo-celinta waa la xafiday. Geli erey-furaha si aad dib ugu soo celiso.','This incremental backup needs backup %s, which is no longer in the storage.'=>'Kaydkan kordhinta ah wuxuu u baahan yahay kaydka %s, kaas oo aan hadda ku jirin kaydinta.','Restoring the backup of %1$s (%2$d file parts).'=>'Dib u soo celinta kaydka %1$s (%2$d qaybaha faylka).','%1$s file could not be overwritten because this site is not allowed to change it, and was left as it is: %2$s'=>'Faylka %1$s lama dul qori karin sababtoo ah goobtan looma oggola inay beddesho, waxaana loo daayay siduu ahaa: %2$s' . "\0" . '%1$s faylal lama dul qori karin sababtoo ah goobtan looma oggola inay wax ka beddesho, waxaana looga tagay sidooda: %2$s','Restored %s files.'=>'Waxaa dib loo soo celiyay %s fayl.','%s did not match its checksum after downloading. The copy in storage may be damaged.'=>'%s kuma ekeysnaan qadarkiisa hubinta markii la soo dejiyay ka dib. Nuqulka ku jira kaydinta waxa laga yaabaa inuu waxyeeloobay.','%s did not arrive. Upload it again.'=>'%s ma soo gaarin. Fadlan mar kale soo geli.','Recognised: %s.'=>'La aqoonsaday: %s.','Imported %1$s files into wp-content (%2$s left out: caches, drop-ins and other backup plugins’ folders).'=>'Waxa la geliyay faylasha %1$s galka wp-content (%2$s waa laga tagay: caches, drop-ins iyo galalka kale ee plugins-ka kaydka).','The archive has no database dump, so only files were imported.'=>'Kaydka ma laha kayd-macluumaad daadasho (database dump), sidaas darteed faylasha kaliya ayaa la soo dhoofiyay.','Database restored into %d temporary tables.'=>'Xog-ururinta waxaa lagu soo celiyay %d jadwal oo kumeelgaar ah.','%s has no WordPress tables in it and was skipped.'=>'%s kuma jiraan wax jadwalyo WordPress ah waana laga gudbay.','The backup’s database has no WordPress tables, so nothing was replaced.'=>'Xog-ururinta kaydka ma laha wax shaxan WordPress ah, sidaas darteed waxba lama beddelin.','This backup is of a multisite network. Restoring a network into a single site is not supported.'=>'Koobiyadan kaydka ahi waxay ka timid shabakad mareegyo badan leh (multisite). Dib-u-soo-celinta shabakad lagu celiyo hal mareeg lama taageero.','Moving the content from %1$s to %2$s.'=>'Ka rarida nuxurka %1$s una rarida %2$s.','Restore complete. If you are signed out, sign in with an account from the restored site.'=>'Dib u soo celintu waa dhammaatay. Haddii lagaa saaray, ku gal akoon ka socda bogga dib loo soo celiyay.','Restore complete.'=>'Soo celintii waa dhammaatay.','%1$s — trying again in %2$d seconds.'=>'%1$s — mar labaad la isku dayayaa %2$d ilbidhiqsi gudahood.','Cancelled.'=>'Waa la joojiyay.','Backups go to one storage destination. Edit or remove the one you have to use a different one.'=>'Koobiyada kaydka ah waxay aadaan hal meel oo kaydin ah. Wax ka beddel ama ka saar kan aad haysato si aad mid kale u isticmaasho.','The database file could not be opened.'=>'Faylka kaydka xogta lama furi karin.','The database refused a statement from the backup: %1$s (%2$s…)'=>'Xog-ururintu waxay diidday bayaan ka yimid kaydka: %1$s (%2$s…)','The restored tables could not be swapped in: %s. Your site is unchanged.'=>'Jadwalka dib loo soo celiyay lama beddeli karin: %s. Goobtaadu waxba iskama beddelin.','There is no writable folder for temporary backup files. Make wp-content writable and try again.'=>'Ma jiro fayl loo qori karo oo loogu talagalay faylasha kaydka ku meel gaarka ah. Ka dhig wp-content mid la qori karo oo isku day mar kale.','Could not create a folder for this job.'=>'Lama abuuri karin galka shaqadan.','%s — guides and services'=>'%s — tilmaamaha iyo adeegyada','User guides'=>'Hagayaasha isticmaalaha','Read the %s user guide'=>'Akhriso hagaha isticmaalaha %s','Hide this'=>'Qari tan','Zinn® hosting for WordPress'=>'Martigelinta Zinn® ee WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, kaydinta maalinlaha ah, wareejin bilaash ah iyo qaybta maamulka oo loo dhisay dadka maamula wax ka badan hal goob.','The Zinn® marketplace'=>'Suuqa Zinn®','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Iibso oo iibi goobaha la dhisay, meelaha magacyada iyo meeleynta xiriiriyaha, iyadoo lacagta si ammaan ah loo hayo ilaa labada dhinacba ay ku qancaan.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — kireyso dad shaqo ahaan tan u qabta','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Suuqayada xorta ah ee caalamiga ah: ka baadh in ka badan 10,000 oo adeegyo diyaarsan oo ka yimid qoraayaasha, naqshadeeyayaasha, horumariyayaasha iyo khubarada SEO, ama dheji mashruuc oo u oggolow inay dalab soo gudbiyaan.','See the Zinn Digital® release notes.'=>'Fiiri qoraallada war-saxaafadeedka Zinn Digital®.','The Zinn® update service did not issue a download link for this update. Check that this site can reach the Zinn® platform, then try again.'=>'Adeegga cusboonaysiinta ee Zinn® ma soo saarin xiriirinta soo dejinta ee cusboonaysiintan. Hubi in goobtani ay gaari karto madal-ka Zinn®, ka dibna mar kale isku day.','The update could not be downloaded from the Zinn® update service (%s). Try again in a few minutes.'=>'Cusboonaysiinta lagama soo dejisan karin adeegga cusboonaysiinta ee Zinn® (%s). Ku soo celi dhowr daqiiqo ka dib.','The downloaded update failed its integrity check and was not installed.'=>'Cusboonaysiinta la soo dejiyay kuma guulaysan hubinta saxnimadeeda lamana rakibin.','The zip archive could not be opened. It may be damaged or incomplete.'=>'Kaydka zip-ka lama furi karin. Waxaa laga yaabaa inuu waxyeeloobay ama aanu dhamaystirnayn.','This .wpress file uses a format we cannot read (it may be compressed or encrypted by All-in-One WP Migration). Export it again without encryption.'=>'Faylkan .wpress wuxuu isticmaalayaa qaab aanan akhrin karin (waxaa laga yaabaa in lagu cufay ama lagu siray All-in-One WP Migration). Fadlan mar kale dhoofi adigoon sirin.','This is a Duplicator “DupArchive” (.daf) file. In Duplicator, build the package again with the archive format set to ZIP, then import that.'=>'Kani waa fayl Duplicator “DupArchive” (.daf) ah. Gudaha Duplicator, mar kale dhis xirmada iyadoo qaabka kaydka loo dejiyay ZIP, ka dibna soo geli taas.','This UpdraftPlus database backup is encrypted. Decrypt it in UpdraftPlus (or turn off database encryption and back up again), then import it.'=>'Koobkan kaydka xogta ee UpdraftPlus waa la xafiday. Ka fur xafidaada UpdraftPlus (ama dami xafidaada kaydka xogta oo mar kale koobi samee), ka dibna soo geli.','Database dump'=>'Koobka xogta keydka','%s is not a backup archive we can read (zip, tar, tar.gz, .wpress, .sql or .sql.gz).'=>'%s ma aha kaydka kaydinta oo aan akhrisan karno (zip, tar, tar.gz, .wpress, .sql ama .sql.gz).','Website archive'=>'Kaydka bogga intarneedka','%s has no WordPress content (no wp-content folder and no database dump) in it.'=>'%s kuma jiraan wax kooban WordPress ah (ma jiro galka wp-content mana jiro kaydka xogta).','This .wpress file is encrypted or compressed by All-in-One WP Migration. Export it again with encryption and compression switched off, then import that.'=>'Faylkan .wpress waxaa siray ama cadaadiyay All-in-One WP Migration. Mar kale dhoofso adiga oo daminaya siraynta iyo cadaadinta, ka dibna soo geli.','Other S3-compatible storage'=>'Kayd kale oo la jaanqaadi kara S3','Cloudflare R2, Amazon S3 or S3-compatible'=>'Cloudflare R2, Amazon S3 ama la jaanqaadi kara S3','The storage keys could not be read on this site. Enter the secret key again on the Storage tab.'=>'Furayaasha kaydinta laguma akhriyi karin goobtan. Mar labaad geli furaha sirta ah ee ku yaal tabka Kaydinta.','This kind of storage is not known.'=>'Kaydkan noociisa ah lama yaqaan.','Choose a kind of storage.'=>'Dooro nooc kayd ah.','Enter the bucket name and the access key.'=>'Geli magaca baaldiga iyo furaha gelitaanka.','Enter your Cloudflare account id (or the full R2 endpoint).'=>'Geli aqoonsiga akoonkaaga Cloudflare (ama barta dhammaadka R2 ee buuxda).','Enter the endpoint address of your storage.'=>'Geli ciwaanka barta dhamaadka ee kaydintaada.','Enter the OAuth client id from your Google Cloud project.'=>'Geli OAuth client id ee mashruucaaga Google Cloud.','Dropbox did not return a refresh token. Start the connection again.'=>'Dropbox ma soo celin calaamadda cusboonaysiinta. Xiriirka mar kale bilow.','Dropbox is not connected. Connect it again on the Storage tab.'=>'Dropbox kuma xirna. Mar kale ku xir tabka Kaydinta.','Google did not return a refresh token. Remove this site from your Google account’s third-party access and connect again.'=>'Google ma soo celin calaamadda cusboonaysiinta (refresh token). Ka saar goobtan gelitaanka dhinac saddexaad ee koontadaada Google oo mar kale ku xir.','That file is not in Google Drive any more.'=>'Faylkaas mar dambe kuma jiro Google Drive.','Google Drive is not connected. Connect it again on the Storage tab.'=>'Google Drive kuma xirna. Mar kale ku xidh tabka Kaydinta.','The storage service did not start the upload.'=>'Adeegga kaydinta ma bilaabin soo gelinta.','The storage service sent a reply that could not be read.'=>'Adeegga kaydinta ayaa soo diray jawaab aan la akhriyi karin.','A temporary backup file could not be read.'=>'Fayl kaydinta kumeelgaarka ah lama akhrin karin.','A deploy link is read-only.'=>'Xiriirinta daabacaaddu waa akhris-keliya.','The deploy code has no link for a file this backup needs.'=>'Koodhka daabulidda ma laha xiriiriye faylka ay kaydintani u baahan tahay.','The deploy link'=>'Xiriirinta daabulidda']];